def transform(grid):
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    # The non-background points are the repeated marker color; 3 is the line color.
    background = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row)
              if v != background and v != 3]
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            if r1 == r2:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if out[r1][c] == background:
                        out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
                    if out[r][c1] == background:
                        out[r][c1] = 3
    return out
